from depth import *

Lecture('information-integrity',[
Q('distortion','Источники искажений','Достоверность рассматриваем относительно конкретных сведений и эталона. Сначала разделим, где возникает ошибка: при вводе, передаче, хранении или интерпретации.',[
 O(1),S('Техническое и смысловое искажение','При техническом искажении меняется представление: символ, бит, порядок или часть сообщения. При смысловой ошибке представление может сохраниться точно, но описывать неверный объект, единицу или событие. Разные ошибки требуют разных проверок.','Хеш неизменённого файла не обнаружит, что оператор изначально указал неправильную цену. И наоборот, правильное бизнес-правило не проверяет физическую целостность переданного архива. Нужны оба уровня в зависимости от цели.'),E('Верная цифра в неверной единице','Учебное исходное значение — 12 упаковок по 10 деталей. В отчёте сохранилось число 12, но единица стала «штуки». Символы не изменились, фактическое количество представлено неверно: 12 вместо 120 штук.','Чтобы выявить дефект, сравнивают смысл поля и правило преобразования. Проверка «поле числовое» пройдёт успешно, поэтому она недостаточна. Исправление должно сохранять исходные величины и объяснимое преобразование.')],Check('Число 12 передано без изменения, но упаковки ошибочно стали штуками. Какая проверка нужна?', ['Только сравнение хешей','Проверка единицы и правила преобразования','Только проверка сетевого Link'],1,'Представление числа сохранно, но изменён смысл. Техническая контрольная сумма этого не устанавливает.'),'Искажения различают по месту возникновения и смыслу затронутого значения.'),
Q('denominator','Показатели по записям и полям','Показатель начинается с объекта счёта. Одна ошибочная запись может содержать несколько ошибочных полей, поэтому знаменатели нельзя менять незаметно.',[
 O(2),O(4),S('Что считается ошибкой записи','В учебном показателе запись считают ошибочной, если хотя бы одно проверяемое поле не совпало с заданным эталоном. Если в одной записи два дефекта, она всё равно одна ошибочная запись, но два ошибочных поля.','Сохраняйте позиции записей и перечень полей. Нельзя считать число строк протокола числом ошибочных записей, если протокол содержит отдельную строку на каждое поле. Сначала группируют по объекту.'),E('Один дефект и два знаменателя','Учебные 5 записей по 4 проверяемых поля дают 20 полей. Ошибки находятся в двух полях одной записи. Доля правильных записей 4/5=0,8; правильных полей 18/20=0,9.','Числа не противоречат друг другу. Они отвечают на разные вопросы. Без описания того, что проверялось, слово «достоверность 90%» скрывает, что полностью правильны только четыре записи из пяти.',table(['Единица счёта','Правильных / всего','Доля'],[['Записи','4 / 5','0,8'],['Поля','18 / 20','0,9']],'Два ошибочных поля находятся в одной записи; эталон задан в условии.'))],Check('Два ошибочных поля находятся в одной из пяти записей. Сколько ошибочных записей?', ['1','2','5','10'],0,'Единица счёта — запись; несколько полевых дефектов одной записи не создают новые записи.'),'Знаменатель и правило ошибки фиксируют отдельно для записей и полей.'),
Q('validation','Проверки формата и связей','Контроль должен отвечать на определённый вопрос. Различим допустимость представления, существование связанного объекта и подтверждение факта.',[
 O(3),S('Диапазон и предметное правило','Тип и диапазон отсеивают часть недопустимых значений: отрицательное количество или невозможную дату. Предметное правило проверяет связь: дата возврата не раньше выдачи; товар существует; статус допускает операцию.','Дата 15 марта может быть календарно допустима, но неверна для события 12 марта. Контроль формата не доказывает фактическую истину. Для неё нужен первичный документ или другой согласованный эталон.'),E('Проверка ссылки','Учебная накладная содержит код склада S-9, которого нет в действующем справочнике. Формат «буква-дефис-цифра» соблюдён, но связь недопустима. Документ направляют на разбор, а не присваивают похожий склад S-8.','Автоматическая догадка создаёт правдоподобную, но неверную запись. Исправление требует подтверждённого источника. После уточнения проверяют связанные суммы и доступность, если место влияет на решение.')],Check('Код S-9 имеет верный формат, но отсутствует в справочнике. Что подтверждено?', ['Формат допустим, ссылка не подтверждена','Запись полностью достоверна','Нужно автоматически заменить на S-8'],0,'Проверки формата и существования объекта имеют разный смысл.'),'Формат, диапазон, связи и подтверждение факта образуют разные уровни контроля.'),
Q('representation','Контроль представления при передаче','Для передачи полезны дополнительные признаки, позволяющие обнаружить изменение. Их возможности ограничены выбранным методом.',[
 S('Чётность как простой пример','При чётном контроле к битовой строке добавляют бит так, чтобы число единиц было чётным. У 10110010 четыре единицы, контрольный бит 0. Одно изменение бита нарушит чётность; некоторые пары изменений её сохранят.','Это учебный пример обнаружения части ошибок, а не подтверждение исходного смысла и не защита от намеренной подмены. Он показывает, почему у любого контроля нужно знать класс обнаруживаемых и пропускаемых изменений.'),E('Две ошибки проходят чётность','Исходная строка 10110010 имеет чётную чётность. Если изменить первый и второй биты, получится 01110010: единиц снова четыре. Проверка чётности не обнаружит именно эту пару изменений.','Сравните с одним изменением первого бита: 00110010 содержит три единицы и нарушает контроль. Таким образом, прохождение проверки не доказывает неизменность всей строки.'),S('Контрольная сумма и хеш','Контрольная сумма или хеш сравниваются с доверенным значением для тех же байтов. Несовпадение выявляет различие представления; совпадение оценивается с учётом свойств метода и доверия к эталону. Это не доказательство истинности цены, имени или даты.','Если изменились и файл, и неподтверждённый эталон, сравнение может утратить смысл. Для учебной передачи фиксируют, откуда получено ожидаемое значение и какой именно файл проверен. Проверка одного файла не распространяется на всю папку.')],Check('Что показывает пример чётности с двумя изменёнными битами?', ['Любая ошибка обнаруживается','Некоторые изменения могут пройти проверку','Чётность подтверждает цену товара'],1,'Контроль имеет пределы обнаружения; совпавший признак не гарантирует отсутствие любого изменения.'),'Метод контроля представления выбирают с учётом обнаруживаемых ошибок и доверенного эталона.'),
Q('reconciliation','Сверка и выборка','Для смысловой достоверности нужен источник сравнения и правила сопоставления. Разберём, как отсутствие или дублирование строк влияет на вывод.',[
 S('Ключ и полнота сверки','Записи сопоставляют по устойчивому ключу, а не только по позиции после сортировки. Проверяют совпадение состава: отсутствующие, лишние и повторные ключи. Затем сравнивают нужные поля и единицы.','Если два файла отсортированы по-разному, построчное сравнение может объявить ошибочными все строки. Если ключ дублируется, автоматическое соответствие неоднозначно. Сначала решают проблему идентификации, затем считают показатели.'),E('Итоговая сумма скрывает перестановку','Эталон: товар A=10, B=20. В системе A=20, B=10. Общая сумма в обоих случаях 30, но обе записи неверны относительно эталона.','Сверка итога полезна как дополнительный контроль, но не заменяет сравнение по ключам. В этом примере ошибочные значения взаимно компенсировались. Нельзя исправлять только сумму: она уже совпадает.'),S('Выборка и предел вывода','Проверенные 200 записей описывают именно эту выборку. Перенос доли на весь массив требует подходящего отбора и оценки неопределённости. Случайно выбранные записи и только заранее известные проблемные записи дают разные основания.','Если проверяли лишь ошибки импорта, результат не характеризует весь фонд данных. В отчёте называют объём массива, способ отбора, поля и эталон. Неизвестный эталон также является ограничением.')],Check('Суммы совпали, но значения A и B поменялись местами. Что подтверждено?', ['Все записи правильны','Только совпадение суммы; нужна сверка по ключам','Нужно удалить ключи'],1,'Агрегат скрывает взаимную компенсацию ошибок отдельных объектов.'),'Сверка проверяет состав, ключи, поля и границы выборки, а не только общий итог.'),
Q('correction','Исправление и повторный контроль','Обнаружение дефекта должно завершиться обоснованным исправлением причины и результата. Массовая правка по догадке может увеличить искажение.',[
 O(5),S('Причина, исправление и история','Для дефекта фиксируют объект, неверное и подтверждённое значение, источник, исполнителя и причину. Если ошибку создаёт импорт, исправляют правило и повторяют разрешённую загрузку; одна ручная правка не устраняет повторяемый источник.','История позволяет проверить, что изменено именно нужное поле. Не следует сохранять лишние персональные данные в учебном протоколе. После исправления снова выполняют тот же контроль, чтобы сравнение было осмысленным.'),E('Один исправленный дефект меняет показатели','Учебные 4 записи по 2 поля; в двух разных записях по одной ошибке. Сначала правильных записей 2/4=0,5, полей 6/8=0,75. После исправления одной ошибки — 3/4=0,75 и 7/8=0,875.','Оба знаменателя сохраняются. Удаление проблемной строки вместо исправления изменило бы состав выборки, поэтому новое отношение нельзя было бы назвать результатом той же сверки без пояснения.')],Check('После исправления одной из двух ошибок в разных записях из четырёх сколько полностью правильных записей?', ['2','3','4','8'],1,'Стало три правильные записи из четырёх; второй дефект ещё остаётся.'),'Исправление подтверждают повторной сверкой с тем же составом и эталоном.')
],[('Почему совпавший хеш не доказывает правильную цену?','Он проверяет представление относительно значения контроля, а не смысл исходного бизнес-факта.'),('Как две ошибки могут не изменить общий итог?','Они могут компенсироваться, например при перестановке значений между ключами.'),('Почему после исправления нельзя незаметно удалить неудобные записи из выборки?','Изменится знаменатель и область вывода; сравнение до и после перестанет относиться к одному набору.')],H('Эталон четырёх записей имеет два поля на запись. В системе найдены две ошибки в одной записи, остальные значения совпадают. Затем исправлено одно из этих двух полей.','Посчитайте доли правильных записей и полей до и после; укажите, почему один показатель не изменился.','Сдайте таблицу четырёх отношений и объяснение единицы счёта.','До: записи 3/4=0,75, поля 6/8=0,75. После: записи 3/4=0,75, поля 7/8=0,875. Запись ещё имеет вторую ошибку.'))

Lecture('performance',[
Q('measures','Показатели и граница измерения','Производительность описывают несколькими величинами. Уточним, где начинается запрос, где он считается завершённым и что признаётся успешным результатом.',[
 O(1),S('Время ответа и пропускная способность','Время ответа измеряют от заданного начала до заданного завершения одной операции. Пропускная способность — число завершённых операций за интервал. Отдельно считают ошибочные завершения: быстрый отказ не равен быстрой успешной работе.','Если клиент измеряет до появления сообщения, а сервер — только время вычисления, это разные интервалы. Сравнивать их как один показатель нельзя. Для предметной цели дополнительно подтверждают сохранение или другой требуемый результат.'),E('Отправлено и завершено','За учебные 60 с отправлено 1500 запросов, успешно завершено 1200, ещё 200 завершились ошибкой, 100 не завершились к границе. Успешная пропускная способность — 1200/60=20 оп/с.','1500/60=25 описывает интенсивность отправки. 1400/60≈23,33 описывает все завершения при выбранном счёте, но смешивает успех и ошибку. Выбор показателя должен быть подписан.')],Check('За 60 с успешно завершено 1200 из 1500 отправленных. Успешная пропускная способность?', ['20 оп/с','25 оп/с','1500 оп/с','0,05 оп/с'],0,'В числителе завершённые успешные операции: 1200/60=20.'),'Границы измерения и определение успешного завершения задают до нагрузки.'),
Q('latency','Измерение задержки','Задержка включает вычисление, ожидание ресурсов и передачу. Разделим составляющие, чтобы не приписывать всё время одному процессору.',[
 S('Обработка и ожидание','Учебный запрос может ожидать свободного соединения, блокировки, диска или очереди, затем выполнять вычисление и передавать результат. Низкая загрузка CPU не доказывает, что запрос ничем не ограничен.','Для локализации нужны временные отметки и ресурсы конкретного маршрута. Суммировать интервалы можно только если они не перекрываются. Параллельные операции не всегда дают полное время простым сложением.'),E('Состав времени одной операции','Учебные неперекрывающиеся интервалы: очередь 80 мс, обработка 40, ожидание диска 70, передача 10. Всего 200 мс. Ускорение обработки вдвое даст 180 мс, а не 100.','Изменился только участок 40→20. Остальные 160 мс сохранились. Это объясняет, почему замена процессора может дать небольшой эффект при преобладающем ожидании.',table(['Участок','До, мс','После, мс'],[['Очередь','80','80'],['Обработка','40','20'],['Ожидание диска','70','70'],['Передача','10','10'],['Всего','200','180']],'Учебные интервалы не перекрываются; изменена только обработка.')),
 S('Клиентское и серверное наблюдение','Клиентский тайм-аут сообщает, что клиент не дождался ответа в своём окне. Сервер мог ещё выполнять запрос или уже сохранить результат. Для анализа связывают наблюдения одним идентификатором операции.','Повтор без выяснения судьбы исходного запроса может создать дубль. Нагрузочный тест должен не только считать задержки, но и сохранять связь с успешным предметным результатом.')],Check('В 200 мс входят 40 мс обработки; её сократили до 20, остальные части прежние. Новое время?', ['100 мс','160 мс','180 мс','200 мс'],2,'200−40+20=180 мс. Нельзя переносить ускорение одного участка на весь запрос.'),'Задержку разбирают на участки и ожидания с согласованными границами.'),
Q('statistics','Среднее, распределение и процентиль','Одинаковое среднее может скрывать разные редкие задержки. Рассмотрим исходный ряд и способ вычисления процентиля.',[
 O(2),E('Среднее скрывает хвост','Учебные задержки 100, 100, 100, 100 и 1000 мс. Среднее 280 мс, медиана 100 мс, максимум 1000 мс. У большинства запросов один режим, у последнего — другое влияние на пользователя.','Ни одна из этих величин не является ошибочной, но каждая описывает свой аспект. Сохраняйте размер выборки и интервалы нагрузки. Среднее не определяет вероятность любой конкретной задержки.'),S('Процентиль ближайшего ранга','Для учебного p95 сортируют n значений и берут элемент с номером ceil(0,95n), считая с единицы. При n=10 номер равен 10, поэтому p95 совпадает с максимумом этой маленькой выборки.','Программные средства могут использовать интерполяционные методы. В отчёте указывают принятый метод, чтобы разные числа не казались противоречием. Маленькая выборка плохо описывает устойчивый хвост распределения.')],Check('Для 10 отсортированных значений при ближайшем ранге какой номер задаёт p95?', ['5','9','10','95'],2,'ceil(0,95×10)=ceil(9,5)=10. При другой методике результат может вычисляться иначе.'),'Среднее и процентили интерпретируют вместе с рядом, размером выборки и методом.'),
Q('load','Нагрузка и воспроизводимость прогона','Сравнение имеет смысл при определённом профиле работы. Число пользователей само по себе не задаёт поток запросов.',[
 S('Профиль нагрузки','Описывают виды операций, интенсивность отправки, параллелизм, размеры данных, длительность, паузы и долю ошибок. Два теста с 20 пользователями могут давать разную нагрузку из-за разных действий и ожиданий.','Если в одном тесте пользователи читают справочник, а в другом строят большой отчёт, сравнение итоговой задержки не измеряет одно изменение системы. Сначала фиксируют сценарий и исходное состояние данных.'),S('Прогрев и кэш','Первый запрос может включать загрузку данных и подготовку кэша, последующие — использовать готовые результаты. Холодный и прогретый режимы полезны, но их разделяют в протоколе.','Не удаляйте медленный первый запуск без объяснения. Если пользователи часто начинают с холодного состояния, он относится к их реальному опыту. Для сравнения нескольких вариантов используйте одинаковый порядок подготовки.'),E('Несопоставимые прогоны','A выполнялся на 10 тысячах записей с прогретым кэшем, B — на миллионе после перезапуска. Задержка B выше; из этого нельзя выделить влияние только новой версии приложения.','Нужно удержать данные и подготовку либо исследовать факторы отдельно. Вывод «версия стала медленнее» сейчас является гипотезой, потому что изменилось несколько условий.')],Check('Чтобы оценить влияние одной настройки, какие два условия полезно сохранить?', ['Одинаковый профиль операций и данные','Одинаковую подготовку и метод измерения','Разные операции в каждом тесте','Разный состав ошибок без учёта'],[0,1],'Сопоставимость требует контролировать остальные условия, иначе причина различия не выделена.'),'Профиль нагрузки и исходное состояние являются частью измеряемого эксперимента.'),
Q('resources','Ресурсы и насыщение','Ресурс может ограничивать поток, но высокий процент сам по себе ещё не доказывает причину. Свяжем загрузку, очередь и изменение результата.',[
 O(3),S('CPU, память, диск и сеть','Проверяют вычислительную загрузку, давление на память, ожидание операций хранения, пропускную способность и очереди сети. Важно соответствие времени наблюдения задержкам нужных запросов.','Свободная память может использоваться кэшем, а диск может задерживать запросы при невысокой средней передаче. Не выбирайте узкое место по одному самому большому проценту. Сначала сформулируйте причинную гипотезу.'),E('Гипотеза о хранилище','Учебный прогон: CPU 35%, очередь операций диска растёт, задержка диска 45 мс. После одного изменения хранения — CPU 45%, диск 8 мс, время ответа ниже при той же нагрузке.','Наблюдения поддерживают гипотезу ограничения хранения, но не гарантируют единственную причину. Повторите сопоставимый прогон и проверьте ошибки. Рост CPU здесь может означать, что процессор меньше ждёт данные.')],Check('Какое свидетельство сильнее поддерживает гипотезу узкого места?', ['Один высокий процент без времени','Связь задержки, очереди и результата после одного контролируемого изменения','Название самого дорогого компонента'],1,'Нужно связать ресурс с нужной функцией и проверить влияние, а не выбрать показатель по внешнему впечатлению.'),'Узкое место подтверждают связью ресурса, ожидания и эффекта контролируемого изменения.'),
Q('experiment','Сравнение вариантов и проверка эффекта','Применим измерения к двум прогонам. Сначала сохраняем одинаковые определения показателей, затем сравниваем эффект и ошибки.',[
 O(4),E('Ускорение и доля ошибок','Учебные прогоны одинакового потока по 1000 запросов: A — 980 успешных, среднее успешных 250 мс; B — 800 успешных, среднее успешных 180 мс. Только по среднему нельзя признать B лучшим.','B быстрее отвечает оставшимся успешным запросам, но теряет существенно больше операций. Нужно рассмотреть требования к успеху и общую работу. Быстрый отказ может искусственно улучшить сводную задержку, если его смешали с успешными ответами.'),S('Повтор и альтернативное объяснение','Повторяют прогон в сопоставимых условиях, сохраняют ряд значений и ресурсы. Если эффект нестабилен, проверяют фоновую нагрузку, кэш, данные и порядок запусков. Одно наблюдение не превращают в универсальный предел системы.','Для учебного отчёта достаточно честно отделить результат конкретного прогона и гипотезу причины. Скрывать неудачный повтор ради красивого среднего нельзя. Все варианты должны иметь одинаковые критерии отбора.')],Check('B быстрее по успешным ответам, но имеет 20% ошибок против 2% у A. Что обосновано?', ['B безусловно лучше','Нужно оценить оба требования: задержку и успешность','Ошибки не относятся к производительности'],1,'Пользовательская функция требует результата; уменьшение времени с ростом ошибок не доказывает улучшения услуги.'),'Эффект оценивают по сопоставимым прогонам вместе с успешностью и повторяемостью.'),
Q('report','Измерение и вывод о расширении','Закончим процедурой, которая позволяет другому сотруднику воспроизвести эксперимент и проверить предложение по расширению.',[
 O(5),S('Протокол измерения','Протокол содержит цель, объект, конфигурацию, данные, нагрузку, подготовку, границы времени, счётчики, метод статистики, ошибки и ресурсы. Вывод связывает наблюдаемое ограничение с предлагаемым действием.','Без исходных данных нельзя пересчитать p95, а без определения завершения — пропускную способность. Сохраните и исходный ряд, и итоговые значения. Параметры реальных пользователей заменяют разрешёнными учебными данными.'),E('Расширение после доказанного ограничения','Учебный результат: при той же нагрузке изменение хранения снизило задержку и не увеличило ошибки. Предложение расширить подсистему хранения теперь имеет экспериментальное основание; требуемую ёмкость и стоимость считают отдельно.','Не переносите вывод на любой сервер предприятия. Назовите исследованный маршрут и условия. После реализации повторяют тот же сценарий и проверяют сохранность данных, а не только скорость копирования.')],Check('Что необходимо для воспроизводимого p95?', ['Только итог 300 мс','Исходные значения, размер выборки и метод расчёта','Только число пользователей'],1,'Без ряда и метода нельзя проверить, какое значение соответствует принятому процентилю.'),'Предложение об улучшении опирается на воспроизводимый протокол и подтверждённое ограничение.')
],[('Чем интенсивность отправки отличается от успешной пропускной способности?','Первая считает отправленные запросы, вторая — успешные завершения за интервал.'),('Почему низкий CPU не исключает узкого места?','Запросы могут ждать диск, блокировку, сеть или свободное соединение.'),('Какие условия нужны для причинного сравнения двух прогонов?','Одинаковые данные, профиль, подготовка, методы и учёт ошибок; меняется исследуемый фактор.')],H('За 120 с отправлено 1800 запросов, успешно завершено 1440, с ошибкой — 240, остальные не завершились. Выборка задержек успешных: 100, 120, 140, 160, 180 мс.','Определите успешную пропускную способность, долю успешных из отправленных, среднее и учебный p95 ближайшего ранга.','Сдайте четыре подписанных показателя и ограничение маленькой выборки задержек.','12 оп/с; 1440/1800=0,8; среднее 140 мс; p95 при n=5 — пятое значение 180 мс. Выборка задержек не описывает автоматически все запросы.'))

Lecture('improvement',[
Q('baseline','Исходное требование и причина потери функции','Меру выбирают относительно конкретного требования и выявленной причины. Перечень полезных технологий не является обоснованием их применения.',[
 S('От последствия к критерию','Для функции определяют допустимый перерыв, требуемое сохранение данных, режим нагрузки и границу обслуживания. Затем анализируют, какие события нарушают эти условия и какие свидетельства это подтверждают.','Если недопустима даже короткая остановка процесса, одна высокая средняя готовность недостаточна. Если главный ущерб связан с потерей данных, второй работающий узел без нужной версии данных может не решить задачу.'),E('Две разные проблемы','Учебная A: сервис редко отказывает, но восстановление занимает 8 ч из-за отсутствия инструкции. B: восстановление 10 минут, но общий источник питания вызывает частые остановки. Одинаковая покупка второго диска не объясняет решение обеих проблем.','В A сначала исследуют организацию и процедуру возврата; в B — общую физическую причину и требуемую независимость. Выбор не должен подменять установленную причину доступной для покупки деталью.'),S('Проверяемая цель меры','Учебная цель «сократить полный интервал восстановления с 4 до не более 1 ч на разрешённом сценарии» задаёт исходное значение, предел и проверку. «Повысить надёжность» без показателя не позволяет принять результат.','Сначала определяют, какие события и время будут измеряться одинаково до и после. Ориентир времени не назначается как официальный норматив курса; здесь это условие учебного решения.')],Check('Восстановление задерживается из-за отсутствия процедуры. Что непосредственно связано с причиной?', ['Только новый корпус сервера','Подготовка и испытание воспроизводимой процедуры восстановления','Замена названия приложения'],1,'Процедура воздействует на выявленную задержку. Покупка оборудования требует отдельного основания.'),'Мера должна воздействовать на установленную причину и проверяться по конкретному требованию.'),
Q('methods','Резервирование и отказоустойчивость','Различим наличие резервного ресурса, сохранение функции при отказе и последующее восстановление. Это разные результаты.',[
 O(1),S('Сохранение функции и возврат','Отказоустойчивость предполагает продолжение требуемой функции при предусмотренных отказах в заданных пределах. Восстановимость — способность вернуть работоспособность. Резерв является средством, которое может поддержать одно или оба свойства.','Резервная копия помогает возврату данных, но не обязана обеспечивать непрерывную работу. Второй канал может сохранять доступ, но не восстанавливает удалённую запись. По каждой мере формулируйте конкретный эффект.'),E('Резерв не независим от общей причины','Учебные два сервера подключены к одному коммутатору без альтернативного пути. Отказ сервера предусмотрен, отказ коммутатора — нет. Утверждение «комплекс выдерживает любой одиночный отказ» не подтверждено.','Чтобы принять такую формулировку, нужен перечень одиночных отказов и реальные проверки соответствующих путей. Из одного успешного переключения нельзя вывести покрытие любого компонента.')],Check('Чем копия базы отличается от работающего резервного канала?', ['Ничем','Копия сохраняет версию для восстановления; канал может поддерживать текущую функцию','Копия гарантирует нулевой перерыв'],1,'Эффекты относятся к разным механизмам; их нельзя подменять одним словом «резерв».'),'Резерв оценивают по функции, предусмотренному отказу и общим зависимостям.'),
Q('recovery','Резервные копии и время возврата','Восстановление требует подходящей версии данных, доступного ресурса и отработанного порядка. Файл копии — лишь одно из условий.',[
 S('Допустимая потеря и длительность возврата','Отдельно задают, сколько последних изменений допустимо потерять и сколько времени допустимо восстанавливаться. Частота создания копий влияет на доступные версии, а скорость восстановления — на длительность возврата. Эти требования не равны.','Копия раз в сутки может быть быстро восстановима, но не содержать последние 20 часов записей. И частые копии могут восстанавливаться слишком долго. Нужны две самостоятельные проверки по условиям задачи.'),S('Копия, конфигурация и зависимости','Для возврата могут потребоваться данные, схема базы, конфигурация приложения, подходящие версии и разрешённый доступ. Все элементы должны относиться к согласованному состоянию. Копия на том же отказавшем носителе не обеспечивает независимый путь.','Перечень восстанавливаемого комплекта проверяют опытом в изолированном месте. Не копируйте секреты в публичный паспорт; доступ организуется отдельно. Учебное восстановление не должно заменять рабочую базу.'),E('Интервал копирования','Учебное требование допускает потерю не более 2 ч изменений. Единственная копия создаётся ежедневно в 02:00; отказ в 20:00 оставляет разрыв 18 ч. Быстрое восстановление этой копии не выполняет требование к потере данных.','Это вывод для заданного события и отсутствия других способов восстановления. Журнал изменений или репликация могут изменить условия, но их нельзя считать существующими без сведений.')],Check('Копия 02:00, отказ 20:00, других источников нет. Каков возраст доступной версии?', ['2 ч','18 ч','20 мин','0 ч'],1,'От 02:00 до 20:00 прошло 18 ч. Длительность фактического восстановления считается отдельно.'),'Версия данных и время восстановления проверяются независимо по заданным пределам.'),
Q('maintenance','Регламентное обслуживание','Профилактика должна иметь цель, периодичность, исполнителя и критерий завершения. Регламент не превращается в бесконечную замену исправных компонентов.',[
 O(2),S('Обслуживание по объекту и наблюдениям','Регламент включает применимые проверки питания, места, журналов, копий, конфигураций и согласованных обновлений. Конкретный состав зависит от оборудования и инструкции производителя. Операции фиксируют с результатом, а не только отметкой посещения.','Если накопитель копий заполнен, действие связывают с сохранением нужной глубины восстановления и правилами хранения. Удаление архива без основания не считается профилактикой. Сначала определяют требуемые данные и разрешённый порядок.'),E('Окно обслуживания и обратимость','Учебное обновление сервиса требует согласованного окна, проверенной копии, совместимости версий, плана возврата и контрольной операции. Само успешное завершение установщика не подтверждает работу приложения.','Перед возвратом пользователей проверяют чтение, запись, права и обмен. Если контроль не пройден, выполняют заранее согласованную ветвь остановки или возврата. Не импровизируют с рабочими данными после начала инцидента.')],Check('Установщик завершился без ошибки. Что нужно для завершения обслуживания?', ['Сразу считать услугу исправной','Выполнить заданные контрольные операции и проверить зависимости','Удалить план возврата'],1,'Установщик проверяет свой процесс, а не всю предметную функцию.'),'Обслуживание связано с конкретной целью, обратимостью и проверкой функции.'),
Q('justification','Расчёт эффекта и выбор меры','Сравним меры по требованию и расчёту. Одинаковый прирост коэффициента может требовать разной цены и давать разные длительности перерывов.',[
 O(3),O(4),E('Сравнение по обязательному пределу','Учебные данные: Tн=100 ч. Мера A даёт Tв=2 ч, мера B — 1 ч. Требование Tв≤1,5 ч обязательно. Хотя обе повышают готовность относительно 4 ч, A не проходит предел, B проходит.','Сначала фильтруют обязательное условие, затем сравнивают стоимость и дополнительные последствия. Низкая цена A не компенсирует невыполнение уже заданного предела. Если требование изменилось, выбор пересчитывают.'),S('Результат расчёта и неопределённость','Предполагаемое сокращение восстановления является входным допущением до испытания. Расчёт показывает, что получится при его выполнении. Он не подтверждает, что команда действительно восстановит сервис за это время.','В предложении разделяют исходные наблюдения, ожидаемый эффект, стоимость и способ проверки. Если данных о достижимом времени нет, это пробел для пилотного испытания, а не повод подставить удобную единицу.')],Check('A даёт 2 ч восстановления, B — 1 ч; обязательный предел 1,5 ч. Что проходит фильтр?', ['Обе, потому что лучше исходного','Только B','Только A','Ни одна'],1,'Улучшение относительно прошлого не заменяет выполнение обязательного текущего требования.'),'Обоснование разделяет обязательные условия, расчётный эффект, стоимость и непроверенные допущения.'),
Q('verification','Испытание выбранной меры','Завершим курс планом, который подтверждает результат, а также обнаруживает, что он не достигнут. Проверка должна иметь исходное состояние и измеряемое окончание.',[
 O(5),S('Сценарий, измерение и конечная операция','На разрешённом стенде определяют отказный сценарий, старт времени, действия, момент подтверждения функции и проверку данных. Выполняют возврат исходной конфигурации и сохраняют все результаты, включая неудачный запуск.','Если измеряется полное восстановление, ожидание и контроль нельзя убрать из секундомера после теста. Если проверяется переключение, нужна допустимая нагрузка на оставшийся путь. Исходный критерий остаётся неизменным.'),E('Достигнутая мера и границы','Учебный тест: старт нарушения 10:00, запуск службы 10:35, контрольная запись успешна 10:50. Полное подтверждённое восстановление — 50 минут. При пределе 60 минут данный сценарий прошёл; другие виды отказов не испытаны.','Не записывайте 35 минут как полный результат и не распространяйте один сценарий на все аварии. Для зачёта объясните модель, вычисление, границы и то, чем испытание подтверждает конкретное улучшение.')],Check('Старт 10:00, служба запущена 10:35, функция подтверждена 10:50. Полное восстановление по критерию функции?', ['35 мин','50 мин','15 мин','0 мин'],1,'Окончание определяется контрольной функцией: от 10:00 до 10:50 прошло 50 минут.'),'Меру принимают по фактическому испытанию функции, времени, данных и возврата.')
],[('Почему резерв не гарантирует отказоустойчивость всей ИС?','Могут остаться общие причины, недостаточная нагрузочная способность и непроверенное переключение.'),('Чем ограничение потери данных отличается от ограничения восстановления?','Первое относится к давности доступной версии, второе — к длительности возврата функции.'),('Как отличить ожидаемый эффект от подтверждённого?','Ожидаемый выведен из допущений расчёта; подтверждённый получен в определённом испытании с исходными данными и конечной проверкой.')],H('Исходно Tн=100 ч и Tв=4 ч. Мера A даёт 2 ч за 20 условных единиц, B — 1 ч за 35; обязательный предел Tв≤1,5 ч.','Рассчитайте исходную и обе ожидаемые готовности, выберите допустимую меру и опишите испытание.','Для подготовки к зачёту свяжите выбор с формулой, обязательным пределом и проверяемым окончанием восстановления.','Исходно 100/104≈0,9615; A:100/102≈0,9804; B:100/101≈0,9901. Допустима B. Испытание измеряет весь заданный интервал до подтверждения функции; расчёт пока ожидаемый.'))
